import React from 'react';
import { FormItem, FormButtonGroup, Submit, Upload, FormLayout } from '@storage-fe/formily-arco';
import { createForm } from '@formily/core';
import { FormProvider, createSchemaField } from '@formily/react';

const SchemaField = createSchemaField({
  components: {
    Upload,
    FormItem,
  },
});

const form = createForm();

export default () => (
  <FormProvider form={form}>
    <FormLayout labelCol={6} wrapperCol={10}>
      <SchemaField>
        <SchemaField.Array name="upload" title="上传" x-decorator="FormItem" x-component="Upload" required />
        <SchemaField.Array
          name="upload2"
          title="卡片上传"
          x-decorator="FormItem"
          x-component="Upload"
          required
          x-component-props={{
            listType: 'picture-card',
            multiple: true,
            action: 'https://run.mocky.io/v3/ab18da7a-2628-4fb9-8310-4525a29ef2e6',
          }}
        />
        <SchemaField.Array
          name="upload3"
          title="拖拽上传"
          x-decorator="FormItem"
          x-component="Upload"
          required
          x-component-props={{
            multiple: true,
            drag: true,
          }}
        />
      </SchemaField>
      <FormButtonGroup.FormItem>
        <Submit onSubmit={console.log}>提交</Submit>
      </FormButtonGroup.FormItem>
    </FormLayout>
  </FormProvider>
);
